"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8921],{7709:a=>{a.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Flashback","desc":"Flashback records gameplay on the server into a compact binary replay and\\nplays it back on the client or inside Studio.\\n\\nServer:\\n\\tlocal Flashback = require(ReplicatedStorage.Flashback)\\n\\tlocal rec = Flashback.Recorder.new({ tickRate = 15 })\\n\\trec:start()\\n\\tlocal blob = rec:stop()\\n\\tFlashback.Store.save(\\"match_1\\", blob)\\n\\nClient or Studio:\\n\\tlocal player = Flashback.Player.new(blob)\\n\\tplayer:play()\\n\\nThe Studio plugin installs a server Script that calls Flashback.Studio.serve()\\nso play tests can be recorded from the plugin.","source":{"line":21,"path":"packages/src/Flashback/init.luau"}}')}}]);